  "claims": [
    {
      "claim": "Direct human absolute oral bioavailability values for steroid-like molecules in the visible contexts are all below 20% (β-sitosterol 0.41%, testosterone undecanoate 6.83%, danazol 11–19% fasted, abiraterone acetate <10% fasted), and phenolic steroid contexts are consistently low or poor (fulvestrant, thienorphine, nestorone, DMAU).",
      "card_ids": ["C01","C04","C08","C05","C17","C33","C14","C22","C31","C09","C10","C11","C12","C15","C20","C24","C27","C29","C30","C23","C06","C07"]
    },
    {
      "claim": "L4 shows the closest scaffold, estradiol, has very low aqueous solubility (3.90 mg/L, C188; 1.81 µg/mL in buffer, C193; ~3.9 mg/L, C183; very low water solubility, C151; low free solubility in cell culture medium, C152/C173), supporting an absorption limitation for the estradiol-like query.",
      "card_ids": ["C188","C193","C183","C151","C152","C173"]
    },
    {
      "claim": "L4 high permeability records are for testosterone (Caco-2 Papp ~5–10×10^-5 cm/s) and prednisolone (human Peff 4.4×10^-4 cm/s), not for the query or estradiol; they do not provide direct F evidence and do not outweigh the low-F contexts and estradiol solubility limitation.",
      "card_ids": ["C166","C191","C158","C185","C187"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C188","C193","C183","C151","C152","C173"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for the query molecule itself.",
    "No query-specific IV-oral comparison, dose, formulation, or prandial-state data.",
    "L4 solubility and permeability records are for estradiol, testosterone, and prednisolone, not the query; estradiol is closest but not identical.",
    "No query-specific first-pass metabolism, efflux, or intestinal metabolism data.",
    "Transfer from L1/L2 low-F contexts is structural inference; the query lacks the long-chain, ester, amine, or acid liabilities of those contexts."
  ],
  "decision_summary": "L4 solubility records for the closest estradiol scaffold show very low aqueous solubility, reinforcing an absorption limitation; high permeability records for other steroids are not query-specific and do not provide F evidence. Combined with direct low-F outcomes for steroid-like contexts, F >= 20% remains unsupported; prediction low."
}

